mapper.select:
SELECT tf.id, tf.arcr_regn AS arcrRegn, tf.arcr_acname AS arcrAcname, tf.arcr_custom_num AS arcrCustomNum, tf.arcr_start_date AS arcrStartDate, tf.arcr_end_date AS arcrEndDate, tf.flno, tc.cstm_name AS arcrName, tc.cstm_region AS cstmRegion FROM T_FLIGHT_CODE_TEMPORARY tf LEFT JOIN T_CUSTOM tc ON TRIM(LEADING '0' FROM tf.arcr_custom_num) = TRIM(LEADING '0' FROM tc.cstm_num)
and tf.arcr_regn = #{arcrRegn}
and tf.arcr_acname = #{arcrAcname}
and tf.arcr_custom_num = #{arcrCustomNum}
and tf.flno = #{flno}

SELECT id, arcr_regn AS arcrRegn, arcr_acname AS arcrAcname, arcr_custom_num AS arcrCustomNum, arcr_start_date AS arcrStartDate, arcr_end_date AS arcrEndDate, flno FROM T_FLIGHT_CODE_TEMPORARY
and id = #{id}
and arcr_regn = #{arcrRegn}
and flno = #{flno}
and (flno is null or flno='')
